const fs = require('fs');
const path = require('path');
const glob = require('glob');

function flatten(obj, prefix = '') {
    let result = {};
    for (const key in obj) {
        const fullKey = prefix ? `${prefix}.${key}` : key;
        if (typeof obj[key] === 'object' && obj[key] !== null && !Array.isArray(obj[key])) {
            Object.assign(result, flatten(obj[key], fullKey));
        } else {
            result[fullKey] = obj[key];
        }
    }
    return result;
}

const enLocales = flatten(JSON.parse(fs.readFileSync('src/i18n/locales/en.json', 'utf8')));
const deLocales = flatten(JSON.parse(fs.readFileSync('src/i18n/locales/de.json', 'utf8')));

const files = glob.sync('src/**/*.{ts,tsx}');

const missingEn = new Set();
const missingDe = new Set();
const hardcodedStrings = [];

const tRegex = /(?:^|\W)i18n\.t\(\s*['"](.+?)['"]|(?:\W|^)t\(\s*['"](.+?)['"]/g;
// Simplified regex for text nodes and attributes
const jsxTextRegex = />([^<>{}\s][^<>{}]*[^<>{}\s])</g;
const attrRegex = /(?:placeholder|title|aria-label|alt)=["']([^"']+)["']/g;
const dialogRegex = /(?:alert|confirm|prompt|toast\.(?:success|error|loading))\(['"]([^'"]+)['"]/g;

files.forEach(file => {
    const content = fs.readFileSync(file, 'utf8');
    const lines = content.split('\n');

    // Scans for t('key')
    let match;
    while ((match = tRegex.exec(content)) !== null) {
        const key = match[1] || match[2];
        if (!enLocales[key]) missingEn.add(key);
        if (!deLocales[key]) missingDe.add(key);
    }

    lines.forEach((line, index) => {
        const lineNum = index + 1;
        if (line.includes('console.') || line.includes('import') || line.includes('className=')) return;

        // JSX Text
        let m;
        while ((m = jsxTextRegex.exec(line)) !== null) {
            const text = m[1].trim();
            if (text && !text.match(/^#[0-9a-fA-F]{3,6}$/) && !text.match(/^\//) && text.length > 2) {
                hardcodedStrings.push({ file, line: lineNum, text, type: 'JSX Text' });
            }
        }
        // Attributes
        while ((m = attrRegex.exec(line)) !== null) {
            const text = m[1].trim();
            if (text && text.length > 1) {
                hardcodedStrings.push({ file, line: lineNum, text, type: 'Attribute' });
            }
        }
        // Dialogs/Toasts
        while ((m = dialogRegex.exec(line)) !== null) {
            const text = m[1].trim();
            hardcodedStrings.push({ file, line: lineNum, text, type: 'Dialog/Toast' });
        }
    });
});

const result = {
    missingKeys: {
        en: Array.from(missingEn),
        de: Array.from(missingDe)
    },
    hardcodedStrings: hardcodedStrings
};

fs.writeFileSync('i18n-audit.json', JSON.stringify(result, null, 2));

console.log('--- i18n Audit Summary ---');
console.log(`Missing en keys: ${result.missingKeys.en.length}`);
console.log(`Missing de keys: ${result.missingKeys.de.length}`);
console.log(`Hardcoded strings: ${result.hardcodedStrings.length}`);
console.log('\nTop 30 Findings (Hardcoded):');
result.hardcodedStrings.slice(0, 30).forEach(s => {
    console.log(`[${s.type}] ${s.file}:${s.line} - "${s.text}"`);
});
console.log('\nAudit results saved to i18n-audit.json');

#!/usr/bin/env node

/**
 * Quick Tile Generator using Planetiler
 * Downloads OSM data and generates PMTiles for Germany
 * 
 * Requirements:
 * - Node.js 18+
 * - Java 17+
 * - ~10GB free disk space
 * - Good internet connection
 * 
 * Usage: node generate-tiles.js
 */

import { exec } from 'child_process';
import { promisify } from 'util';
import fs from 'fs';
import https from 'https';
import path from 'path';

const execAsync = promisify(exec);

const PLANETILER_VERSION = '0.7.0';
const PLANETILER_JAR = `planetiler-dist-${PLANETILER_VERSION}.jar`;
const PLANETILER_URL = `https://github.com/onthegomap/planetiler/releases/download/v${PLANETILER_VERSION}/${PLANETILER_JAR}`;

const OSM_DATA_URL = 'https://download.geofabrik.de/europe/germany-latest.osm.pbf';
const OSM_DATA_FILE = 'germany-latest.osm.pbf';

const OUTPUT_FILE = 'germany.pmtiles';
const OUTPUT_DIR = './tiles-output';

// Colors for terminal
const colors = {
  reset: '\x1b[0m',
  cyan: '\x1b[36m',
  green: '\x1b[32m',
  yellow: '\x1b[33m',
  red: '\x1b[31m'
};

function log(message, color = colors.reset) {
  console.log(`${color}${message}${colors.reset}`);
}

function downloadFile(url, dest) {
  return new Promise((resolve, reject) => {
    const file = fs.createWriteStream(dest);

    https.get(url, (response) => {
      const totalSize = parseInt(response.headers['content-length'], 10);
      let downloadedSize = 0;

      response.pipe(file);

      response.on('data', (chunk) => {
        downloadedSize += chunk.length;
        const percentage = ((downloadedSize / totalSize) * 100).toFixed(1);
        process.stdout.write(`\r${colors.yellow}Downloading: ${percentage}%${colors.reset}`);
      });

      file.on('finish', () => {
        file.close();
        console.log(''); // New line
        resolve();
      });
    }).on('error', (err) => {
      fs.unlink(dest, () => {});
      reject(err);
    });
  });
}

async function checkJava() {
  try {
    const { stdout } = await execAsync('java -version 2>&1');
    log('Ô£ô Java detected', colors.green);
    return true;
  } catch {
    log('ÔØî Java not found. Please install Java 17 or higher', colors.red);
    log('Download from: https://adoptium.net/', colors.yellow);
    return false;
  }
}

async function downloadPlanetiler() {
  if (fs.existsSync(PLANETILER_JAR)) {
    log('Ô£ô Planetiler already downloaded', colors.green);
    return;
  }

  log('­ƒôÑ Downloading Planetiler...', colors.cyan);
  await downloadFile(PLANETILER_URL, PLANETILER_JAR);
  log('Ô£ô Planetiler downloaded', colors.green);
}

async function downloadOsmData() {
  if (fs.existsSync(OSM_DATA_FILE)) {
    log('Ô£ô OSM data already downloaded', colors.green);
    return;
  }

  log('­ƒôÑ Downloading Germany OSM data (~3.5GB)...', colors.cyan);
  log('ÔÅ▒´©Å  This may take 10-30 minutes depending on your connection', colors.yellow);
  await downloadFile(OSM_DATA_URL, OSM_DATA_FILE);
  log('Ô£ô OSM data downloaded', colors.green);
}

async function generateTiles() {
  if (!fs.existsSync(OUTPUT_DIR)) {
    fs.mkdirSync(OUTPUT_DIR, { recursive: true });
  }

  const outputPath = path.join(OUTPUT_DIR, OUTPUT_FILE);

  if (fs.existsSync(outputPath)) {
    log('Ô£ô Tiles already generated', colors.green);
    log(`­ƒôì Location: ${outputPath}`, colors.cyan);
    return;
  }

  log('­ƒö¿ Generating tiles...', colors.cyan);
  log('ÔÅ▒´©Å  This will take 30-90 minutes', colors.yellow);
  log('­ƒÆ¥ Peak memory usage: ~4-6GB RAM', colors.yellow);

  const command = `java -Xmx6g -jar ${PLANETILER_JAR} ` +
    `--download ` +
    `--area=germany ` +
    `--output=${outputPath} ` +
    `--maxzoom=15 ` +
    `--min_feature_size=0.25 ` +
    `--min_feature_size_at_max_zoom=0.01 ` +
    `--simplify_tolerance=0.05 ` +
    `--simplify_tolerance_at_max_zoom=0.02 ` +
    `--schema=protomaps ` +
    `--force`;

  try {
    const { stdout, stderr } = await execAsync(command, { maxBuffer: 10 * 1024 * 1024 });

    if (stdout) console.log(stdout);
    if (stderr) console.error(stderr);

    log('Ô£ô Tiles generated successfully!', colors.green);
    log(`­ƒôì Output: ${outputPath}`, colors.cyan);

    const stats = fs.statSync(outputPath);
    const sizeMB = (stats.size / 1024 / 1024).toFixed(2);
    log(`­ƒôè File size: ${sizeMB} MB`, colors.cyan);

  } catch (error) {
    log('ÔØî Tile generation failed', colors.red);
    console.error(error);
    process.exit(1);
  }
}

async function main() {
  log('ÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉ', colors.cyan);
  log('   GPS Tracker - Tile Generator', colors.cyan);
  log('ÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉ', colors.cyan);
  log('');

  // Check Java
  const hasJava = await checkJava();
  if (!hasJava) {
    process.exit(1);
  }

  log('');
  log('­ƒôï Process:', colors.cyan);
  log('  1. Download Planetiler (~40MB)', colors.reset);
  log('  2. Download Germany OSM data (~3.5GB)', colors.reset);
  log('  3. Generate PMTiles (~2-4GB output)', colors.reset);
  log('');
  log('ÔÅ▒´©Å  Total time: 30 minutes - 2 hours', colors.yellow);
  log('­ƒÆ¥ Disk space needed: ~10GB', colors.yellow);
  log('');

  // Confirm
  log('Press Ctrl+C to cancel, or wait 5 seconds to start...', colors.yellow);
  await new Promise(resolve => setTimeout(resolve, 5000));

  try {
    // Step 1: Download Planetiler
    log('');
    log('ÔöüÔöüÔöü Step 1/3: Download Planetiler ÔöüÔöüÔöü', colors.cyan);
    await downloadPlanetiler();

    // Step 2: Download OSM data
    log('');
    log('ÔöüÔöüÔöü Step 2/3: Download OSM Data ÔöüÔöüÔöü', colors.cyan);
    await downloadOsmData();

    // Step 3: Generate tiles
    log('');
    log('ÔöüÔöüÔöü Step 3/3: Generate Tiles ÔöüÔöüÔöü', colors.cyan);
    await generateTiles();

    // Success
    log('');
    log('ÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉ', colors.green);
    log('   Ô£ô TILE GENERATION COMPLETE!', colors.green);
    log('ÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉÔòÉ', colors.green);
    log('');
    log('­ƒôì Output location:', colors.cyan);
    log(`   ${path.resolve(OUTPUT_DIR, OUTPUT_FILE)}`, colors.reset);
    log('');
    log('­ƒôñ Next steps:', colors.cyan);
    log('  1. Upload to your server:', colors.reset);
    log(`     scp ${OUTPUT_DIR}/${OUTPUT_FILE} user@yourserver.com:/var/www/html/tiles/`, colors.yellow);
    log('  2. Update app tile server URL:', colors.reset);
    log('     src/services/offlineTileDownloader.ts', colors.yellow);
    log('  3. Configure CORS on your server', colors.reset);
    log('  4. Test download in app!', colors.reset);
    log('');

  } catch (error) {
    log('');
    log('ÔØî Process failed', colors.red);
    console.error(error);
    process.exit(1);
  }
}

main();

import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import { Toaster } from 'react-hot-toast';
import { useTranslation } from 'react-i18next';
import { useEffect, useState } from 'react';
import OrdersMainPage from './components/Web/Orders/OrdersMainPage';
import AdminPage from './components/Web/Admin/AdminPage';
import { DatabaseStatusIndicator } from './components/GPS/DatabaseStatusIndicator';
import AuthScreen from './components/Auth/AuthScreen';
import { AuthProvider, useAuth } from './context/AuthContext';
import { useDarkMode } from './hooks/useDarkMode';
import NotificationContainer from './components/ui/NotificationContainer';
import { ConfirmationProvider } from './components/ui/ConfirmationProvider';
import { AnimatedLoader } from './components/ui/AnimatedLoader';
import ErrorBoundary from './components/ErrorBoundary';
import { ReloadPrompt } from './components/ReloadPrompt';
import { clearStartupRecoveryMarker, triggerAutomaticStartupRecovery } from './utils/startupRecovery';
import './index.css';

// Import auth persistence test in development
if (import.meta.env.DEV) {
  import('./utils/testAuth');
  // Make Firebase sync debugger available globally in dev mode
  import('./utils/firebaseSyncDebugger');
  // Import auth token utilities for debugging
  import('./utils/authTokenUtils');
  // Import admin status checker
  import('./utils/checkAdminStatus');
}

// Protected route wrapper
function ProtectedRoute({ element }: { element: React.ReactNode }) {
  const auth = useAuth();

  // Handle HMR race condition where context might not be ready
  if (!auth) {
    return null; // Context not ready, render nothing
  }

  // If we already have an authenticated user, do not block on loading forever.
  if (auth.loading && auth.isAuthenticated) {
    return element;
  }

  // Still loading auth state - don't show AuthScreen yet
  if (auth.loading) {
    return null; // Let the main auth provider handle loading state
  }

  // Show login if not authenticated
  if (!auth.isAuthenticated) {
    return <AuthScreen />;
  }

  return element;
}

// Main app content
function AppContent() {
  const [isDarkMode] = useDarkMode();
  const auth = useAuth();
  const { t } = useTranslation();
  const [allowAuthFallback, setAllowAuthFallback] = useState(false);

  const handleForceAuthFallback = () => {
    setAllowAuthFallback(true);
    void triggerAutomaticStartupRecovery('auth-init-timeout').catch(error => {
      console.warn('Manual startup recovery failed from app shell:', error);
    });
  };

  useEffect(() => {
    let cancelled = false;

    if (!auth.loading) {
      setAllowAuthFallback(false);
      clearStartupRecoveryMarker();
      return () => {
        cancelled = true;
      };
    }

    const timer = setTimeout(() => {
      if (cancelled || !auth.loading) return;

      void triggerAutomaticStartupRecovery('auth-init-timeout')
        .catch(error => {
          console.warn('Auto startup recovery failed from app shell:', error);
        })
        .finally(() => {
          if (!cancelled) {
            setAllowAuthFallback(true);
          }
        });
    }, 12000);

    return () => {
      cancelled = true;
      clearTimeout(timer);
    };
  }, [auth.loading]);

  // Show loading screen while auth is being resolved
  if (auth.loading && !allowAuthFallback && !auth.isAuthenticated) {
    return (
      <div className={isDarkMode ? 'dark' : ''}>
        <div className="min-h-screen bg-gray-50 dark:bg-gray-900 flex flex-col items-center justify-center px-4">
          <AnimatedLoader message={t('common.loadingAuth') || 'Loading'} />
          <button
            type="button"
            onClick={handleForceAuthFallback}
            className="mt-4 px-4 py-2 rounded-lg border text-sm font-medium transition-colors bg-white text-gray-700 border-gray-300 hover:bg-gray-100 dark:bg-gray-800 dark:text-gray-200 dark:border-gray-600 dark:hover:bg-gray-700"
          >
            {t('common.continueToLogin') || 'Continue to login'}
          </button>
        </div>
      </div>
    );
  }

  if (allowAuthFallback && !auth.isAuthenticated) {
    return <AuthScreen />;
  }

  return (
    <NotificationContainer>
      <ReloadPrompt />
      <div className={isDarkMode ? 'dark' : ''}>
        <div className="min-h-screen bg-gray-50 dark:bg-gray-900">
          <Routes>
            <Route
              path="/"
              element={<ProtectedRoute element={<OrdersMainPage />} />}
            />
            <Route
              path="/admin"
              element={<ProtectedRoute element={<AdminPage />} />}
            />
            <Route
              path="*"
              element={<ProtectedRoute element={<OrdersMainPage />} />}
            />
          </Routes>

        <Toaster
          position="bottom-center"
          toastOptions={{
            duration: 3000,
            style: {
              background: isDarkMode ? '#1f2937' : '#ffffff',
              color: isDarkMode ? '#f3f4f6' : '#111827',
              cursor: 'pointer',
            },
            onClick: (event, toast) => {
              // Dismiss the toast when clicked
              if (toast && toast.id) {
                import('react-hot-toast').then(module => module.default.dismiss(toast.id));
              }
            },
          }}
        />
        </div>
      </div>
    </NotificationContainer>
  );
}

function App() {
  return (
    <ErrorBoundary>
      <AuthProvider>
        <ConfirmationProvider>
          <Router>
            <AppContent />
          </Router>
        </ConfirmationProvider>
      </AuthProvider>
    </ErrorBoundary>
  );
}

export default App;

