interface Migration {
  version: number;
  description: string;
  up: (db: SQLiteDBConnection) => Promise<void>;
  down?: (db: SQLiteDBConnection) => Promise<void>; // Rollback support
}

interface MigrationRecord {
  version: number;
  description: string;
  applied_at: string;
  duration_ms: number;
  success: boolean;
  error_message?: string;
}

