  lines.push('Z;Proben und Untersuchung;lfd.Nr. /GPS;T├╝tenbarcode;Schlagnr.;Teilschlagnr.;Schlagname;Erweiterung Schlagname;Schlaggr├Â├ƒe [ha];Proben-Fl├ñche [ha];Nutzung [A/W/R/O/H/U];Erntereste abg. [j/n];Transport-tracking-nr.;Bodenart;Humusklasse;Standard pH/P/K/Mg');

  // Sample data (H lines)
  samples.forEach((sample, index) => {
