/**
 * Main export function
 */
export async function exportSamplesToLaboratory(
  samples: GpsSample[],
  options: LaboratoryExportOptions
): Promise<ExportResult> {
  try {
    // Validate all samples
    const validationErrors: string[] = [];
    samples.forEach(sample => {
      const errors = validateSampleForExport(sample, options.laboratory);
      validationErrors.push(...errors);
    });

    if (validationErrors.length > 0) {
      return {
        success: false,
        filename: '',
        validationErrors
      };
    }

    // Generate export data
    let data: Blob;
    let filename: string;

    const timestamp = new Date().toISOString().split('T')[0];
    const labPrefix = options.laboratory.toLowerCase();

    if (options.format === 'XLSX') {
      const buffer = generateXLSX(samples, options);
      data = new Blob([buffer], { 
        type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' 
      });
      filename = `${labPrefix}_export_${timestamp}.xlsx`;
    } else if (options.format === 'CSV') {
      let csvContent: string;
      switch (options.laboratory) {
        case 'Agrolab':
          csvContent = generateAgrolabCSV(samples, options);
          break;
        case 'LUFA':
          csvContent = generateLUFACSV(samples, options);
          break;
        default:
          csvContent = generateGenericCSV(samples);
      }
      data = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      filename = `${labPrefix}_export_${timestamp}.csv`;
    } else {
      return {
        success: false,
        filename: '',
        error: 'XML format not yet implemented'
      };
    }

    return {
      success: true,
      filename,
      data
    };

  } catch (error: any) {
    return {
      success: false,
      filename: '',
      error: error.message || 'Export failed'
    };
  }
}

/**
 * Download export file
 */
export function downloadExport(result: ExportResult) {
  if (!result.success || !result.data) {
    throw new Error(result.error || 'No data to download');
  }

  const url = URL.createObjectURL(result.data);
  const link = document.createElement('a');
  link.href = url;
  link.download = result.filename;
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  URL.revokeObjectURL(url);
}

/**
 * Log export activity for compliance tracking
 */
export async function logExportActivity(
  exportResult: ExportResult,
  samples: GpsSample[],
  options: LaboratoryExportOptions,
  userId: string
) {
  const logEntry = {
    timestamp: new Date().toISOString(),
    user_id: userId,
    laboratory: options.laboratory,
    format: options.format,
    sample_count: samples.length,
    success: exportResult.success,
    filename: exportResult.filename,
    validation_errors: exportResult.validationErrors,
    error: exportResult.error
  };

  // Store in local storage for now
  // TODO: Implement proper export log service with Firebase/database storage
  const logs = JSON.parse(localStorage.getItem('laboratory_export_logs') || '[]');
  logs.push(logEntry);
  localStorage.setItem('laboratory_export_logs', JSON.stringify(logs.slice(-100))); // Keep last 100

  return logEntry;
}

/**
 * Role-Based Access Control (RBAC) Service
 * Manages user roles and permissions for the soil sampling platform
 */

import type { UserRole } from '../types';
import { auth } from '../firebase';
import { firebaseGPS } from './firebaseSync';

export interface UserWithRole {
  uid: string;
  email: string;
  role: UserRole;
  organization_id?: string;
  displayName?: string;
  created_at: string;
  lastActive: string;
}

export interface Permission {
  resource: string;
  action: 'create' | 'read' | 'update' | 'delete' | 'export';
  granted: boolean;
}

/**
 * Role permissions matrix
 * Defines what each role can do
 */
const ROLE_PERMISSIONS: Record<UserRole, string[]> = {
  admin: [
    'users:*',
    'projects:*',
    'samples:*',
    'exports:*',
    'organizations:*',
    'settings:*'
  ],
  consultant: [
    'projects:read',
    'projects:create',
    'projects:update',
    'samples:read',
    'samples:create',
    'samples:update',
    'exports:create',
    'exports:read',
    'users:read' // Can view users in their organization
  ],
  client: [
    'projects:read',
    'samples:read',
    'exports:read'
  ],
  lab_manager: [
    'exports:read',
    'exports:create',
    'samples:read',
    'samples:update', // Can update lab-related fields only
    'projects:read'
  ],
  technician: [
    'projects:read',
    'samples:create',
    'samples:read',
    'samples:update'
  ]
};

/**
 * Check if a role has a specific permission
 */
export function hasPermission(role: UserRole, resource: string, action: string): boolean {
  const permissions = ROLE_PERMISSIONS[role] || [];

  // Check for exact match
  const permissionKey = `${resource}:${action}`;
  if (permissions.includes(permissionKey)) {
    return true;
  }

  // Check for wildcard match
  const wildcardKey = `${resource}:*`;
  if (permissions.includes(wildcardKey)) {
    return true;
  }

  return false;
}

/**
 * Get user role from Firestore
 */
export async function getUserRole(uid: string): Promise<UserRole | null> {
  try {
    const userDoc = await firebaseGPS.getUserDocument(uid);
    return (userDoc?.role as UserRole) || null;
  } catch (error) {
    console.error('Error fetching user role:', error);
    return null;
  }
}

/**
 * Get current user's role
 */
export async function getCurrentUserRole(): Promise<UserRole | null> {
  const user = auth.currentUser;
  if (!user) return null;

  return getUserRole(user.uid);
}

/**
 * Check if current user has permission
 */
export async function currentUserCan(resource: string, action: string): Promise<boolean> {
  const role = await getCurrentUserRole();
  if (!role) return false;

  return hasPermission(role, resource, action);
}

/**
 * Update user role (admin only)
 */
export async function updateUserRole(uid: string, role: UserRole): Promise<void> {
  // Check if current user is admin
  const currentRole = await getCurrentUserRole();
  if (currentRole !== 'admin') {
    throw new Error('Only administrators can update user roles');
  }

  try {
    await firebaseGPS.updateUserRole(uid, role);
  } catch (error: any) {
    console.error('Error updating user role:', error);
    throw new Error(`Failed to update user role: ${error.message}`);
  }
}

/**
 * Get human-readable role name
 */
export function getRoleName(role: UserRole): string {
  const roleNames: Record<UserRole, string> = {
    admin: 'Administrator',
    client: 'Client',
    consultant: 'Consultant',
    lab_manager: 'Lab Manager',
    technician: 'Technician'
  };
  return roleNames[role] || role;
}

/**
 * Get role description
 */
export function getRoleDescription(role: UserRole): string {
  const descriptions: Record<UserRole, string> = {
    admin: 'Full system access, can manage users and organizations',
    client: 'View projects and samples, download exports',
    consultant: 'Create and manage projects, perform sampling, export data',
    lab_manager: 'Manage laboratory exports and sample analysis data',
    technician: 'Perform field sampling and data entry'
  };
  return descriptions[role] || '';
}

/**
 * Get all available roles
 */
export function getAllRoles(): UserRole[] {
  return ['admin', 'consultant', 'lab_manager', 'technician', 'client'];
}

/**
 * Validate if a user can access another user's data
 */
export async function canAccessUserData(
  currentUserId: string,
  targetUserId: string
): Promise<boolean> {
  // User can always access their own data
  if (currentUserId === targetUserId) {
    return true;
  }

  const currentRole = await getUserRole(currentUserId);

  // Admins can access anyone's data
  if (currentRole === 'admin') {
    return true;
  }

  // Check if users are in the same organization
  const currentUser = await firebaseGPS.getUserDocument(currentUserId);
  const targetUser = await firebaseGPS.getUserDocument(targetUserId);

  if (
    currentUser?.organization_id &&
    targetUser?.organization_id &&
    currentUser.organization_id === targetUser.organization_id
  ) {
    // Consultants can access data from their organization
    if (currentRole === 'consultant') {
      return true;
    }
  }

  return false;
}

/**
 * Check if user can export samples
 */
export async function canExportSamples(): Promise<boolean> {
  return await currentUserCan('exports', 'create');
}

/**
 * Check if user can manage users
 */
export async function canManageUsers(): Promise<boolean> {
  const role = await getCurrentUserRole();
  return role === 'admin';
}

/**
 * Check if user can create projects
 */
export async function canCreateProjects(): Promise<boolean> {
  return await currentUserCan('projects', 'create');
}

/**
 * Get permissions for a role
 */
export function getRolePermissions(role: UserRole): Permission[] {
  const permissions: Permission[] = [];
  const rolePerms = ROLE_PERMISSIONS[role] || [];

  // Parse permissions into structured format
  const resources = ['users', 'projects', 'samples', 'exports', 'organizations', 'settings'];
  const actions: Array<'create' | 'read' | 'update' | 'delete' | 'export'> = [
    'create',
    'read',
    'update',
    'delete',
    'export'
  ];

  for (const resource of resources) {
    for (const action of actions) {
      permissions.push({
        resource,
        action,
        granted: hasPermission(role, resource, action)
      });
    }
  }

  return permissions;
}

/**
 * On-demand tile download service
 * Downloads map tiles dynamically when user navigates to areas without offline coverage
 */

import { Capacitor } from '@capacitor/core';

interface TileCoordinate {
  x: number;
  y: number;
  zoom: number;
}

interface TileBounds {
  north: number;
  south: number;
  east: number;
  west: number;
}

// Lower Saxony bounds (pre-downloaded offline tiles)
const LOWER_SAXONY_BOUNDS: TileBounds = {
  north: 53.9,
  south: 51.3,
  east: 11.6,
  west: 6.7
};

// Track downloaded tiles
const downloadedTiles = new Set<string>();
const downloadQueue = new Map<string, Promise<void>>();

// Tile template (self-hosted only). Must be configured via VITE_ONLINE_TILE_URL.
const ONLINE_TILE_TEMPLATE = (import.meta.env.VITE_ONLINE_TILE_URL as string | undefined) || '';

/**
 * Check if coordinates are within Lower Saxony (offline coverage area)
 */
function isInLowerSaxony(lat: number, lon: number): boolean {
  return (
    lat >= LOWER_SAXONY_BOUNDS.south &&
    lat <= LOWER_SAXONY_BOUNDS.north &&
    lon >= LOWER_SAXONY_BOUNDS.west &&
    lon <= LOWER_SAXONY_BOUNDS.east
  );
}

/**
 * Convert lat/lon to tile coordinates
 */
function latLonToTile(lat: number, lon: number, zoom: number): TileCoordinate {
  const latRad = (lat * Math.PI) / 180;
  const n = Math.pow(2, zoom);
  const x = Math.floor(((lon + 180) / 360) * n);
  const y = Math.floor(((1 - Math.asinh(Math.tan(latRad)) / Math.PI) / 2) * n);
  return { x, y, zoom };
}

/**
 * Convert tile coordinates to lat/lon bounds
 */
function tileToBounds(x: number, y: number, zoom: number): TileBounds {
  const n = Math.pow(2, zoom);
  const west = (x / n) * 360 - 180;
  const east = ((x + 1) / n) * 360 - 180;
  const northRad = Math.atan(Math.sinh(Math.PI * (1 - (2 * y) / n)));
  const southRad = Math.atan(Math.sinh(Math.PI * (1 - (2 * (y + 1)) / n)));
  const north = (northRad * 180) / Math.PI;
  const south = (southRad * 180) / Math.PI;
  return { north, south, east, west };
}

/**
 * Get unique key for tile
 */
function getTileKey(x: number, y: number, zoom: number): string {
  return `${zoom}/${x}/${y}`;
}

/**
 * Download a single tile and cache it
 */
async function downloadTile(x: number, y: number, zoom: number): Promise<void> {
  const key = getTileKey(x, y, zoom);

  // Check if already downloaded
  if (downloadedTiles.has(key)) {
    return;
  }

  // Check if already downloading
  if (downloadQueue.has(key)) {
    return downloadQueue.get(key);
  }

  // Start download
  const downloadPromise = (async () => {
    try {
      if (!ONLINE_TILE_TEMPLATE) {
        throw new Error('No online tile template configured (VITE_ONLINE_TILE_URL).');
      }

      const url = ONLINE_TILE_TEMPLATE
        .replace('{z}', String(zoom))
        .replace('{x}', String(x))
        .replace('{y}', String(y));
      const response = await fetch(url);

      if (!response.ok) {
        throw new Error(`Failed to download tile: ${response.status}`);
      }

      const blob = await response.blob();

      // Cache in IndexedDB or localStorage
      await cacheTile(key, blob);

      downloadedTiles.add(key);
      console.log(`[TileDownload] Ô£à Downloaded tile: ${key}`);
    } catch (error) {
      console.error(`[TileDownload] ÔØî Failed to download tile ${key}:`, error);
    } finally {
      downloadQueue.delete(key);
    }
  })();

  downloadQueue.set(key, downloadPromise);
  return downloadPromise;
}

/**
 * Cache tile in IndexedDB
 */
async function cacheTile(key: string, blob: Blob): Promise<void> {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open('MapTilesCache', 1);

    request.onerror = () => reject(request.error);

    request.onupgradeneeded = (event) => {
      const db = (event.target as IDBOpenDBRequest).result;
      if (!db.objectStoreNames.contains('tiles')) {
        db.createObjectStore('tiles');
      }
    };

    request.onsuccess = () => {
      const db = request.result;
      const transaction = db.transaction(['tiles'], 'readwrite');
      const store = transaction.objectStore('tiles');

      const putRequest = store.put(blob, key);

      putRequest.onsuccess = () => resolve();
      putRequest.onerror = () => reject(putRequest.error);
    };
  });
}

/**
 * Get cached tile from IndexedDB
 */
export async function getCachedTile(x: number, y: number, zoom: number): Promise<Blob | null> {
  const key = getTileKey(x, y, zoom);

  return new Promise((resolve) => {
    const request = indexedDB.open('MapTilesCache', 1);

    request.onerror = () => resolve(null);

    request.onsuccess = () => {
      const db = request.result;

      if (!db.objectStoreNames.contains('tiles')) {
        resolve(null);
        return;
      }

      const transaction = db.transaction(['tiles'], 'readonly');
      const store = transaction.objectStore('tiles');
      const getRequest = store.get(key);

      getRequest.onsuccess = () => {
        resolve(getRequest.result || null);
      };

      getRequest.onerror = () => resolve(null);
    };
  });
}

/**
 * Request tiles for a map viewport
 * Downloads tiles outside Lower Saxony on-demand
 */
export async function requestTilesForViewport(
  bounds: TileBounds,
  zoom: number,
  maxZoom: number = 15
): Promise<void> {
  // Only download up to max zoom
  if (zoom > maxZoom) {
    zoom = maxZoom;
  }

  // Get center of viewport
  const centerLat = (bounds.north + bounds.south) / 2;
  const centerLon = (bounds.east + bounds.west) / 2;

  // Check if we're in Lower Saxony
  if (isInLowerSaxony(centerLat, centerLon)) {
    // Already have offline tiles
    return;
  }

  // Calculate which tiles are visible
  const topLeft = latLonToTile(bounds.north, bounds.west, zoom);
  const bottomRight = latLonToTile(bounds.south, bounds.east, zoom);

  console.log(`[TileDownload] Requesting tiles for viewport outside Lower Saxony (zoom ${zoom})`);

  // Download visible tiles
  const downloadPromises: Promise<void>[] = [];

  for (let x = topLeft.x; x <= bottomRight.x; x++) {
    for (let y = topLeft.y; y <= bottomRight.y; y++) {
      downloadPromises.push(downloadTile(x, y, zoom));

      // Limit concurrent downloads
      if (downloadPromises.length >= 6) {
        await Promise.all(downloadPromises);
        downloadPromises.length = 0;
      }
    }
  }

  // Wait for remaining downloads
  if (downloadPromises.length > 0) {
    await Promise.all(downloadPromises);
  }
}

/**
 * Clear tile cache
 */
export async function clearTileCache(): Promise<void> {
  return new Promise((resolve, reject) => {
    const request = indexedDB.deleteDatabase('MapTilesCache');
    request.onsuccess = () => {
      downloadedTiles.clear();
      console.log('[TileDownload] Ô£à Tile cache cleared');
      resolve();
    };
    request.onerror = () => reject(request.error);
  });
}

/**
 * Get cache statistics
 */
export async function getTileCacheStats(): Promise<{ count: number; sizeEstimate: string }> {
  return new Promise((resolve) => {
    const request = indexedDB.open('MapTilesCache', 1);

    request.onerror = () => resolve({ count: 0, sizeEstimate: '0 MB' });

    request.onsuccess = () => {
      const db = request.result;

      if (!db.objectStoreNames.contains('tiles')) {
        resolve({ count: 0, sizeEstimate: '0 MB' });
        return;
      }

      const transaction = db.transaction(['tiles'], 'readonly');
      const store = transaction.objectStore('tiles');
      const countRequest = store.count();

      countRequest.onsuccess = () => {
        const count = countRequest.result;
        const sizeEstimate = ((count * 15) / 1024).toFixed(2) + ' MB'; // ~15KB per tile
        resolve({ count, sizeEstimate });
      };

      countRequest.onerror = () => resolve({ count: 0, sizeEstimate: '0 MB' });
    };
  });
}

export default {
  requestTilesForViewport,
  getCachedTile,
  clearTileCache,
  getTileCacheStats
};

