/**
 * Backup and Export Utilities
 * Fixes Issue #29: No backup/export system
 * 
 * Provides comprehensive backup/restore functionality for:
 * - Full database export (all projects, tracks, GPS points, samples, boundaries)
 * - Selective export (specific projects or date ranges)
 * - Automatic scheduled backups
 * - Import/restore from backup files
 * - Cloud backup support (Firebase Storage)
 */

import { logger } from '../services/logger';
import { EXPORT_FORMATS } from '../config/constants';

export interface BackupMetadata {
  version: string;
  timestamp: string;
  appVersion: string;
  platform: string;
  userId: string;
  itemCounts: {
    projects: number;
    tracks: number;
    gpsPoints: number;
    samples: number;
    boundaries: number;
    devices: number;
  };
  size: number; // bytes
}

export interface BackupData {
  metadata: BackupMetadata;
  data: {
    projects: any[];
    tracks: any[];
    gpsPoints: any[];
    samples: any[];
    boundaries: any[];
    devices: any[];
  };
}

export interface BackupOptions {
  includeProjects?: boolean;
  includeTracks?: boolean;
  includeGpsPoints?: boolean;
  includeSamples?: boolean;
  includeBoundaries?: boolean;
  includeDevices?: boolean;
  projectIds?: string[]; // Specific projects to backup
  dateFrom?: Date; // Only backup data after this date
  dateTo?: Date; // Only backup data before this date
  compress?: boolean; // Compress backup (future: gzip)
}

export interface RestoreOptions {
  overwrite?: boolean; // Overwrite existing data
  mergeStrategy?: 'skip' | 'replace' | 'merge'; // How to handle conflicts
  validateBeforeRestore?: boolean; // Validate backup integrity
}

export interface BackupSchedule {
  enabled: boolean;
  frequency: 'daily' | 'weekly' | 'monthly';
  time?: string; // HH:MM format
  maxBackups: number; // Keep last N backups
  autoCleanup: boolean; // Delete old backups
}

/**
 * Export full database to JSON
 */
export async function exportDatabase(
  databaseService: any,
  options: BackupOptions = {}
): Promise<BackupData> {
  logger.info('Backup', 'Starting database export', { options });

  const startTime = Date.now();

  // Default: export everything
  const opts = {
    includeProjects: true,
    includeTracks: true,
    includeGpsPoints: true,
    includeSamples: true,
    includeBoundaries: true,
    includeDevices: true,
    ...options
  };

  const data: BackupData['data'] = {
    projects: [],
    tracks: [],
    gpsPoints: [],
    samples: [],
    boundaries: [],
    devices: []
  };

  try {
    // Export projects
    if (opts.includeProjects) {
      const projects = await databaseService.getProjects();
      data.projects = filterByDate(projects, opts.dateFrom, opts.dateTo, 'created_at');

      // Filter by specific project IDs if provided
      if (opts.projectIds && opts.projectIds.length > 0) {
        data.projects = data.projects.filter((p: any) => 
          opts.projectIds!.includes(p.id)
        );
      }
    }

    // Export tracks
    if (opts.includeTracks) {
      const projectIds = data.projects.map((p: any) => p.id);
      for (const projectId of projectIds) {
        const projectData = await databaseService.getProjects();
        const project = projectData.find((p: any) => p.id === projectId);
        if (project?.tracks) {
          data.tracks.push(...project.tracks);
        }
      }
    }

    // Export GPS points
    if (opts.includeGpsPoints) {
      // GPS points are nested in tracks
      for (const track of data.tracks) {
        if (track.gps_points) {
          data.gpsPoints.push(...track.gps_points);
        }
      }
    }

    // Export samples
    if (opts.includeSamples) {
      for (const track of data.tracks) {
        if (track.samples) {
          data.samples.push(...track.samples);
        }
      }
    }

    // Export boundaries
    if (opts.includeBoundaries) {
      const projectIds = data.projects.map((p: any) => p.id);
      for (const projectId of projectIds) {
        const boundaries = await databaseService.getFieldBoundaries(projectId);
        data.boundaries.push(...boundaries);
      }
    }

    // Export devices
    if (opts.includeDevices) {
      const devices = await databaseService.getDevices();
      data.devices = devices;
    }

    const duration = Date.now() - startTime;

    // Create metadata
    const metadata: BackupMetadata = {
      version: '1.0',
      timestamp: new Date().toISOString(),
      appVersion: '1.0.0', // Should come from package.json
      platform: navigator.platform,
      userId: '', // Should be filled by caller
      itemCounts: {
        projects: data.projects.length,
        tracks: data.tracks.length,
        gpsPoints: data.gpsPoints.length,
        samples: data.samples.length,
        boundaries: data.boundaries.length,
        devices: data.devices.length
      },
      size: 0 // Will be calculated after stringification
    };

    const backup: BackupData = { metadata, data };

    // Calculate size
    const jsonString = JSON.stringify(backup);
    backup.metadata.size = new Blob([jsonString]).size;

    logger.info('Backup', 'Database export complete', {
      duration,
      itemCounts: metadata.itemCounts,
      size: metadata.size
    });

    return backup;
  } catch (error) {
    logger.error('Backup', 'Database export failed', error);
    throw error;
  }
}

/**
 * Save backup to file
 */
export async function saveBackupToFile(
  backup: BackupData,
  filename?: string
): Promise<void> {
  const name = filename || `gps-backup-${backup.metadata.timestamp.split('T')[0]}.json`;
  const jsonString = JSON.stringify(backup, null, 2);
  const blob = new Blob([jsonString], { type: 'application/json' });

  // Create download link
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = name;
  link.click();

  // Cleanup
  setTimeout(() => URL.revokeObjectURL(url), 100);

  logger.info('Backup', 'Backup saved to file', { filename: name, size: blob.size });
}

/**
 * Load backup from file
 */
export async function loadBackupFromFile(file: File): Promise<BackupData> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();

    reader.onload = (event) => {
      try {
        const backup = JSON.parse(event.target?.result as string);

        // Validate backup structure
        if (!backup.metadata || !backup.data) {
          throw new Error('Invalid backup file structure');
        }

        logger.info('Backup', 'Backup loaded from file', {
          version: backup.metadata.version,
          timestamp: backup.metadata.timestamp,
          itemCounts: backup.metadata.itemCounts
        });

        resolve(backup);
      } catch (error) {
        logger.error('Backup', 'Failed to parse backup file', error);
        reject(error);
      }
    };

    reader.onerror = () => {
      logger.error('Backup', 'Failed to read backup file');
      reject(new Error('Failed to read file'));
    };

    reader.readAsText(file);
  });
}

/**
 * Restore database from backup
 */
export async function restoreDatabase(
  databaseService: any,
  backup: BackupData,
  options: RestoreOptions = {}
): Promise<{
  success: boolean;
  imported: BackupMetadata['itemCounts'];
  errors: string[];
}> {
  logger.info('Backup', 'Starting database restore', {
    version: backup.metadata.version,
    itemCounts: backup.metadata.itemCounts,
    options
  });

  const opts = {
    overwrite: false,
    mergeStrategy: 'skip' as const,
    validateBeforeRestore: true,
    ...options
  };

  const imported = {
    projects: 0,
    tracks: 0,
    gpsPoints: 0,
    samples: 0,
    boundaries: 0,
    devices: 0
  };

  const errors: string[] = [];

  try {
    // Validate backup if requested
    if (opts.validateBeforeRestore) {
      const validation = validateBackup(backup);
      if (!validation.valid) {
        throw new Error(`Invalid backup: ${validation.errors.join(', ')}`);
      }
    }

    // Restore projects
    for (const project of backup.data.projects) {
      try {
        await databaseService.createProject(project.name, project.description);
        imported.projects++;
      } catch (error) {
        errors.push(`Project ${project.name}: ${error}`);
      }
    }

    // Restore devices
    for (const device of backup.data.devices) {
      try {
        await databaseService.saveDevice(device);
        imported.devices++;
      } catch (error) {
        errors.push(`Device ${device.name}: ${error}`);
      }
    }

    // Note: Tracks, GPS points, samples, boundaries would need more complex
    // restoration logic to maintain relationships

    logger.info('Backup', 'Database restore complete', { imported, errors: errors.length });

    return {
      success: errors.length === 0,
      imported,
      errors
    };
  } catch (error) {
    logger.error('Backup', 'Database restore failed', error);
    throw error;
  }
}

/**
 * Validate backup integrity
 */
export function validateBackup(backup: BackupData): {
  valid: boolean;
  errors: string[];
  warnings: string[];
} {
  const errors: string[] = [];
  const warnings: string[] = [];

  // Check required fields
  if (!backup.metadata) {
    errors.push('Missing metadata');
  } else {
    if (!backup.metadata.version) errors.push('Missing version');
    if (!backup.metadata.timestamp) errors.push('Missing timestamp');
  }

  if (!backup.data) {
    errors.push('Missing data');
  } else {
    // Verify data arrays
    if (!Array.isArray(backup.data.projects)) errors.push('Projects is not an array');
    if (!Array.isArray(backup.data.tracks)) errors.push('Tracks is not an array');
    if (!Array.isArray(backup.data.gpsPoints)) errors.push('GPS points is not an array');
    if (!Array.isArray(backup.data.samples)) errors.push('Samples is not an array');
    if (!Array.isArray(backup.data.boundaries)) errors.push('Boundaries is not an array');
    if (!Array.isArray(backup.data.devices)) errors.push('Devices is not an array');

    // Verify counts match
    if (backup.data.projects.length !== backup.metadata.itemCounts.projects) {
      warnings.push('Project count mismatch');
    }
  }

  return {
    valid: errors.length === 0,
    errors,
    warnings
  };
}

/**
 * Filter items by date range
 */
function filterByDate(
  items: any[],
  dateFrom?: Date,
  dateTo?: Date,
  dateField: string = 'created_at'
): any[] {
  if (!dateFrom && !dateTo) return items;

  return items.filter(item => {
    const itemDate = new Date(item[dateField]);
    if (dateFrom && itemDate < dateFrom) return false;
    if (dateTo && itemDate > dateTo) return false;
    return true;
  });
}

/**
 * Get backup file size estimate
 */
export function estimateBackupSize(itemCounts: BackupMetadata['itemCounts']): number {
  // Rough estimates per item (in bytes)
  const sizes = {
    project: 200,
    track: 300,
    gpsPoint: 100,
    sample: 150,
    boundary: 500,
    device: 250
  };

  return (
    itemCounts.projects * sizes.project +
    itemCounts.tracks * sizes.track +
    itemCounts.gpsPoints * sizes.gpsPoint +
    itemCounts.samples * sizes.sample +
    itemCounts.boundaries * sizes.boundary +
    itemCounts.devices * sizes.device
  );
}

/**
 * Error Translation Helper
 * Maps error codes to i18n translation keys
 * Fixes Issue #23: Translation keys missing for error messages
 */

import { ERROR_MESSAGES } from '../config/constants';

export type ErrorCategory = 
  | 'database'
  | 'sync' 
  | 'gps'
  | 'device'
  | 'field'
  | 'track'
  | 'sample'
  | 'common';

export interface TranslatedError {
  key: string; // i18n translation key
  category: ErrorCategory;
  message: string; // English fallback
  params?: Record<string, any>; // Parameters for interpolation
}

/**
 * Error code to translation key mapping
 */
const ERROR_KEY_MAP: Record<string, string> = {
  // Auth errors
  'auth/requires-recent-login': 'errors.database.authentication_required',
  'auth/user-not-found': 'errors.database.authentication_required',
  'permission-denied': 'errors.database.permission_denied',

  // Network errors
  'network-request-failed': 'errors.database.network_error',
  'unavailable': 'errors.database.device_offline',
  'timeout': 'errors.database.operation_timeout',

  // Data errors
  'not-found': 'errors.database.not_found',
  'invalid-argument': 'errors.database.invalid_data',
  'already-exists': 'errors.database.invalid_data',

  // Storage errors
  'quota-exceeded': 'errors.database.storage_quota_exceeded',
  'failed-precondition': 'errors.database.database_error',

  // GPS errors
  'POSITION_UNAVAILABLE': 'errors.gps.location_unavailable',
  'PERMISSION_DENIED': 'errors.gps.permission_denied',
  'TIMEOUT': 'errors.gps.timeout',

  // Sync errors
  'sync-failed': 'errors.database.sync_failed',
  'conflict': 'errors.sync.conflict_detected',
};

/**
 * Translate error to i18n key
 */
export function translateError(error: Error | string | any): TranslatedError {
  const errorMsg = typeof error === 'string' ? error : error?.message || error?.code || 'unknown';
  const errorCode = typeof error === 'object' ? error?.code : errorMsg;

  // Try direct mapping first
  if (errorCode && ERROR_KEY_MAP[errorCode]) {
    return {
      key: ERROR_KEY_MAP[errorCode],
      category: getCategoryFromKey(ERROR_KEY_MAP[errorCode]),
      message: errorMsg
    };
  }

  // Pattern matching for common error types
  if (errorMsg.toLowerCase().includes('network')) {
    return {
      key: 'errors.database.network_error',
      category: 'database',
      message: errorMsg
    };
  }

  if (errorMsg.toLowerCase().includes('offline')) {
    return {
      key: 'errors.database.device_offline',
      category: 'database',
      message: errorMsg
    };
  }

  if (errorMsg.toLowerCase().includes('timeout')) {
    return {
      key: 'errors.database.operation_timeout',
      category: 'database',
      message: errorMsg
    };
  }

  if (errorMsg.toLowerCase().includes('permission')) {
    return {
      key: 'errors.database.permission_denied',
      category: 'database',
      message: errorMsg
    };
  }

  if (errorMsg.toLowerCase().includes('not found')) {
    return {
      key: 'errors.database.not_found',
      category: 'database',
      message: errorMsg
    };
  }

  if (errorMsg.toLowerCase().includes('invalid') || errorMsg.toLowerCase().includes('validation')) {
    return {
      key: 'errors.database.invalid_data',
      category: 'database',
      message: errorMsg
    };
  }

  if (errorMsg.toLowerCase().includes('gps') || errorMsg.toLowerCase().includes('location')) {
    return {
      key: 'errors.gps.location_unavailable',
      category: 'gps',
      message: errorMsg
    };
  }

  if (errorMsg.toLowerCase().includes('device') || errorMsg.toLowerCase().includes('bluetooth')) {
    return {
      key: 'errors.device.connection_failed',
      category: 'device',
      message: errorMsg
    };
  }

  // Fallback to unknown error
  return {
    key: 'errors.common.unknown_error',
    category: 'common',
    message: errorMsg
  };
}

/**
 * Get category from translation key
 */
function getCategoryFromKey(key: string): ErrorCategory {
  const parts = key.split('.');
  if (parts.length >= 2 && parts[0] === 'errors') {
    return parts[1] as ErrorCategory;
  }
  return 'common';
}

/**
 * Format error for user display with i18n
 */
export function formatErrorForUser(
  error: Error | string | any,
  t: (key: string, params?: any) => string
): string {
  const translated = translateError(error);

  try {
    // Try translation with params
    const translatedMsg = t(translated.key, translated.params);

    // If translation returns the key itself, use fallback
    if (translatedMsg === translated.key) {
      return translated.message;
    }

    return translatedMsg;
  } catch (e) {
    // Fallback to English message
    return translated.message;
  }
}

/**
 * Check if error is retriable based on translation
 */
export function isRetriableFromTranslation(error: Error | string | any): boolean {
  const translated = translateError(error);

  const retriableKeys = [
    'errors.database.network_error',
    'errors.database.device_offline',
    'errors.database.operation_timeout',
    'errors.database.sync_failed',
    'errors.gps.timeout',
    'errors.device.connection_timeout',
  ];

  return retriableKeys.includes(translated.key);
}

/**
 * Get user-friendly action suggestion based on error
 */
export function getErrorAction(
  error: Error | string | any,
  t: (key: string) => string
): string | null {
  const translated = translateError(error);

  const actionMap: Record<string, string> = {
    'errors.database.device_offline': 'errors.common.try_again',
    'errors.database.network_error': 'errors.common.try_again',
    'errors.database.operation_timeout': 'errors.common.try_again',
    'errors.gps.permission_denied': 'errors.common.contact_support',
    'errors.database.permission_denied': 'errors.common.contact_support',
    'errors.database.storage_quota_exceeded': 'errors.common.contact_support',
  };

  const actionKey = actionMap[translated.key];
  if (actionKey) {
    try {
      return t(actionKey);
    } catch (e) {
      return null;
    }
  }

  return null;
}

/**
 * Create error notification config for toast/snackbar
 */
export interface ErrorNotificationConfig {
  message: string;
  action?: string;
  severity: 'error' | 'warning' | 'info';
  duration?: number;
  retriable: boolean;
}

export function createErrorNotification(
  error: Error | string | any,
  t: (key: string, params?: any) => string
): ErrorNotificationConfig {
  const translated = translateError(error);
  const message = formatErrorForUser(error, t);
  const action = getErrorAction(error, t);
  const retriable = isRetriableFromTranslation(error);

  // Determine severity based on category
  let severity: 'error' | 'warning' | 'info' = 'error';
  if (translated.category === 'sync' || translated.key.includes('offline')) {
    severity = 'warning'; // Offline/sync issues are warnings, not critical
  }

  // Duration based on severity
  const duration = severity === 'error' ? 5000 : 3000;

  return {
    message,
    action: action || undefined,
    severity,
    duration,
    retriable
  };
}

/**
 * GPS Connection Fix Utility
 * Handles the "tcp proxy not installed" error by providing fallback mechanisms
 * and proper error handling for GPS device connections
 */

import { Capacitor } from '@capacitor/core';
import { isCapacitorApp } from './platform';
import GpsDeviceManager from '../plugins/GpsDeviceManager/index';

export interface GpsConnectionDiagnostics {
  isNative: boolean;
  hasGpsManager: boolean;
  capacitorVersion: string;
  platform: string;
  error?: string;
}

/**
 * Diagnose GPS connection capabilities and potential issues
 */
export async function diagnoseGpsConnection(): Promise<GpsConnectionDiagnostics> {
  const diagnostics: GpsConnectionDiagnostics = {
    isNative: isCapacitorApp(),
    hasGpsManager: false,
    capacitorVersion: Capacitor.getPlatform(),
    platform: Capacitor.getPlatform()
  };

  try {
    // Try to check if GPS manager is available
    const status = await GpsDeviceManager.getStatus();
    diagnostics.hasGpsManager = true;
  } catch (error) {
    diagnostics.hasGpsManager = false;
    diagnostics.error = error instanceof Error ? error.message : String(error);
    console.warn('ÔØî GPS Manager not available:', diagnostics.error);
  }

  return diagnostics;
}

/**
 * Fix GPS connection issues by providing appropriate fallbacks
 */
export async function fixGpsConnection(): Promise<{
  success: boolean;
  message: string;
  useNativeGps: boolean;
}> {
  const diagnostics = await diagnoseGpsConnection();

  // If we're on web platform, native GPS won't work
  if (!diagnostics.isNative) {
    return {
      success: false,
      message: 'GPS device connection requires native Android app. Use browser geolocation instead.',
      useNativeGps: false
    };
  }

  // If GPS manager is not available in native app
  if (!diagnostics.hasGpsManager) {
    console.error('GPS Manager Plugin Issue:', diagnostics.error);

    // Common issues and fixes
    if (diagnostics.error?.includes('not implemented')) {
      return {
        success: false,
        message: 'GPS Manager plugin not properly registered. Please restart the app.',
        useNativeGps: false
      };
    }

    if (diagnostics.error?.includes('not found')) {
      return {
        success: false,
        message: 'GPS Manager plugin not found. The app may need to be reinstalled.',
        useNativeGps: false
      };
    }

    return {
      success: false,
      message: `GPS Manager unavailable: ${diagnostics.error}`,
      useNativeGps: false
    };
  }

  // GPS Manager is available
  return {
    success: true,
    message: 'GPS Manager is ready for device connections',
    useNativeGps: true
  };
}

/**
 * Safe GPS device connection with error handling
 */
export async function safeConnectGpsDevice(
  device: {
    address: string;
    connectionType: 'bluetooth' | 'wifi' | 'serial';
    port?: number;
    name?: string;
  }
): Promise<{
  success: boolean;
  message: string;
  connected: boolean;
}> {
  try {
    // First check if GPS connection is possible
    const connectionCheck = await fixGpsConnection();
    if (!connectionCheck.success) {
      return {
        success: false,
        message: connectionCheck.message,
        connected: false
      };
    }

    // Attempt connection
    console.log('­ƒöî Attempting to connect to GPS device:', device);

    const result = await GpsDeviceManager.connectDevice({
      address: device.address,
      connectionType: device.connectionType,
      port: device.port || 9001,
      name: device.name || 'GPS Device'
    });

    console.log('Ô£à GPS device connected successfully:', result);

    return {
      success: true,
      message: `Connected to ${device.name || device.address}`,
      connected: true
    };

  } catch (error) {
    const errorMessage = error instanceof Error ? error.message : String(error);
    console.error('ÔØî GPS connection failed:', errorMessage);

    // Provide user-friendly error messages
    if (errorMessage.includes('not implemented') || errorMessage.includes('not found')) {
      return {
        success: false,
        message: 'GPS device connection requires the native Android app. Web browser cannot connect to external GPS devices.',
        connected: false
      };
    }

    if (errorMessage.includes('permission')) {
      return {
        success: false,
        message: 'Location permissions are required. Please enable location access in device settings.',
        connected: false
      };
    }

    if (errorMessage.includes('timeout') || errorMessage.includes('unreachable')) {
      return {
        success: false,
        message: 'Cannot reach GPS device. Check device IP address and network connection.',
        connected: false
      };
    }

    return {
      success: false,
      message: `Connection failed: ${errorMessage}`,
      connected: false
    };
  }
}

