const isRecoverableDistCleanupError = (error: unknown): error is NodeJS.ErrnoException => {
  if (!error || typeof error !== "object") {
    return false;
  }

  const code = "code" in error ? String((error as NodeJS.ErrnoException).code || "") : "";
  return code === "EBUSY" || code === "EPERM" || code === "ENOTEMPTY";
};

const clearDirectoryContents = (directoryPath: string) => {
  if (!fs.existsSync(directoryPath)) {
    return;
  }

  for (const entry of fs.readdirSync(directoryPath)) {
    const entryPath = path.join(directoryPath, entry);
    try {
      fs.rmSync(entryPath, {
        recursive: true,
        force: true,
        maxRetries: 8,
        retryDelay: 150,
      });
    } catch (error) {
      if (isRecoverableDistCleanupError(error)) {
        console.warn(`ÔÜá´©Å Skipping locked build artifact: ${entryPath}`);
        continue;
      }

      throw error;
    }
  }
};

